ValidationRule.errorConditionFormula:
AND(
				NOT($User.BypassValidationRules__c),
				$Profile.Name <> 'Carmignac - System Administrator',
				$Permission.PRPDCO,
				NOT(
								OR(
												/* Allow all ThirdParties records */
												RecordType.DeveloperName = "ThirdParties",

												/* Allow Third Party Narratives with specific SubTypes */
												AND(
																RecordType.DeveloperName = "Narrative",
																ISPICKVAL(Type__c, "Third Party"),
																OR(
																				ISPICKVAL(SubType__c, "TransferAgent"),
																				ISPICKVAL(SubType__c, "Prime_Agent"),
																				ISPICKVAL(SubType__c, "Pre-central admin"),
																				ISPICKVAL(SubType__c, "Central Admin"),
																				ISPICKVAL(SubType__c, "Central_Admin2")
																)
												),

												/* Allow PRIIPs Narratives */
												AND(
																RecordType.DeveloperName = "Narrative",
																ISPICKVAL(Type__c, "PRIIPs"),
																ISPICKVAL(SubType__c, "Settlement Period")
												)
								)
				)
)
